document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.getAttribute('href')===location.pathname.split('/').pop()));
const toggle=document.getElementById('theme-toggle');
function theme(){const light=document.documentElement.dataset.theme==='light';document.getElementById('theme-icon').textContent=light?'☾':'☀';toggle.setAttribute('aria-label',light?'Switch to dark mode':'Switch to light mode');toggle.setAttribute('aria-pressed',String(light));}
theme();toggle.addEventListener('click',()=>{const value=document.documentElement.dataset.theme==='light'?'dark':'light';document.documentElement.dataset.theme=value;try{localStorage.setItem('inu-theme',value);}catch{}theme();});
document.getElementById('year').textContent=new Date().getFullYear();
document.getElementById('menu').addEventListener('click',()=>{const open=document.getElementById('navigation').classList.toggle('open');document.getElementById('menu').setAttribute('aria-expanded',String(open));});
document.querySelectorAll('[data-link]').forEach(button=>button.addEventListener('click',async()=>{try{const response=await fetch('data/snapshot.json',{cache:'no-store'});const data=await response.json();const url=data.config.links[button.dataset.link];if(url?.startsWith('https://')){window.open(url,'_blank','noopener,noreferrer');return;}}catch{}const toast=document.getElementById('toast');toast.textContent='Official links will be available when InuStrategy launches.';toast.hidden=false;setTimeout(()=>toast.hidden=true,4000);}));
if(document.getElementById('test-metrics')){
 async function refresh(){try{const response=await fetch('data/test-token.json',{cache:'no-store'});if(!response.ok)throw new Error();const data=await response.json();const stale=Date.now()-Date.parse(data.generatedAt)>20*60000;const t=data.token;document.getElementById('test-updated').textContent=`Snapshot: ${new Date(data.generatedAt).toLocaleString()} · ${stale?'STALE — values hidden':t.status} · Highest-liquidity pool`;
 const rows=[['Price (USD)',t.price],['Market cap (USD)',t.marketCap],['Liquidity (USD)',t.liquidity],['24H volume (USD)',t.volume24h],['Total supply',t.totalSupply],['Buys 24H',t.activity.buys],['Sells 24H',t.activity.sells],['Holders',t.holders]];
 document.getElementById('test-metrics').replaceChildren(...rows.map(([label,value])=>{const row=document.createElement('div');row.className='metric';const l=document.createElement('span');l.className='metric-label';l.textContent=label;const v=document.createElement('strong');v.textContent=stale||value==null?'—':value.toLocaleString('en-US',{notation:label==='Price (USD)'?'standard':'compact',maximumFractionDigits:label==='Price (USD)'?8:2});row.append(l,v);return row;}));document.getElementById('test-proof').textContent=data.feeProofSummary;
 }catch{document.getElementById('test-updated').textContent='Test snapshot unavailable.';document.getElementById('test-proof').textContent='No routing result available.';}}await refresh();setInterval(refresh,30000);
}
